// Har lead ke liye agla step nikalo: step 1 day 0, step 2 day 3,
// step 3 day 7 ke baad. Reply/meeting/won/lost wale bahar.
const DONE = ['replied', 'meeting', 'won', 'lost', 'do-not-contact'];
const GAPS = { 2: 3, 3: 7 };
const out = [];
for (const item of $input.all()) {
  const l = item.json;
  if (DONE.includes((l.status || 'new').toLowerCase())) continue;
  const lastStep = parseInt(l.last_step || '0', 10) || 0;
  const nextStep = lastStep + 1;
  if (nextStep > 3) continue;
  if (lastStep > 0) {
    const last = new Date(l.last_contacted_at || Date.now());
    const days = (Date.now() - last.getTime()) / 86400000;
    if (days < GAPS[nextStep]) continue;
  }
  out.push({ json: { ...l, step: nextStep } });
}
return out;

// Step ke hisab se template message banao (Python CLI wale
// templates ke mutabiq). AI node aage isay rewrite kar sakta hai.
const PAIN = {
  'Real Estate': 'leads that message after hours and never hear back until the next day',
  'Dental': 'missed appointment bookings and patients who do not show up',
  'Healthcare': 'a front desk buried in calls and appointment requests',
  'E-commerce': 'abandoned carts and order questions that wait hours for a reply',
  'Legal': 'consultation requests that go unanswered and intake forms that pile up',
};
const out = [];
for (const item of $input.all()) {
  const l = item.json;
  const name = l.contact_name || 'there';
  const pain = PAIN[l.industry] || 'repetitive emails and follow-ups eating hours every week';
  let subject, body;
  if (l.step === 1) {
    subject = `Quick question about ${l.business_name}`;
    body = `Hi ${name},\n\nI help small businesses automate the work that quietly eats hours every week — things like ${pain}.\n\nWould a free 10-minute audit be useful? I'll look at how ${l.business_name} handles follow-ups today and tell you the one thing AI could take off your plate. No pitch, no obligation.\n\nBest,\nMuhammad Asadullah Ibrahim\nAI Automation Specialist`;
  } else if (l.step === 2) {
    subject = `Re: Quick question about ${l.business_name}`;
    body = `Hi ${name},\n\nJust floating this back up — most ${l.industry || 'small business'} businesses I speak to lose enquiries the same way: ${pain}. An AI assistant that replies in seconds usually fixes it in a week.\n\nHappy to show you what that looks like for ${l.business_name} in 10 minutes, if you're curious.\n\nBest,\nMuhammad Asadullah Ibrahim`;
  } else {
    subject = `Closing the loop — ${l.business_name}`;
    body = `Hi ${name},\n\nLast note from me — I don't want to clutter your inbox. If automating follow-ups is on your list this year, I'm here for a quick chat. If not, no worries at all, and I wish ${l.business_name} well.\n\nBest,\nMuhammad Asadullah Ibrahim`;
  }
  out.push({ json: { ...l, subject, body } });
}
return out;

// AI ka jawab (Groq ya Gemini) + template wala message dono yahan milte hain.
// AI ka text nikaalo; kuch usable na mile to template hi aage bhej.
const raw = $input.first().json;
const template = $('Build Message (Template)').first().json;
let text = '';
try { text = raw.choices[0].message.content || ''; } catch (e) {}
if (!text) { try { text = raw.candidates[0].content.parts[0].text || ''; } catch (e) {} }
text = text.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```[a-z]*\n?/gi, '').trim();
const m = text.match(/^Subject:\s*(.+?)\n+([\s\S]+)$/);
if (m && m[1].trim() && m[2].trim()) {
  return [{ json: { ...template, subject: m[1].trim(), body: m[2].trim() } }];
}
// AI se kuch usable nahi mila — template wala message hi aage bhej
return [{ json: template }];

